insert into public.ark60_content(day_number,module,title,status,payload,published_at,updated_at)
values(17,'speaking','Full Speaking · Day 17','published',$json${"version":"speaking-day-17-v1","part1":{"topic":"TOPIC 19. ART","questions":[{"key":"p1_q1","text":"Do you like modern art or traditional art?"},{"key":"p1_q2","text":"Do you like art?"},{"key":"p1_q3","text":"Have you ever visited an art gallery?"},{"key":"p1_q4","text":"Do you think it would be interesting for you to be an artist?"}]},"part2":{"key":"p2_main","topic":"TOPIC 18. ENVIRONMENTAL LAW","prompt":"Describe a law on environmental protection.","bullets":["what the law is","how you first learned about it","who benefits from this law","how you feel about it"],"preparation_seconds":60,"max_answer_seconds":120},"part3":{"topic":"TOPIC 18. RULES AND PUNISHMENT","questions":[{"key":"p3_q1","text":"What can teachers do to make students obey rules?"},{"key":"p3_q2","text":"What are some rules that exist in schools or workplaces in your country?"},{"key":"p3_q3","text":"What should parents do to educate children about laws?"},{"key":"p3_q4","text":"When people break rules, how are they punished in your country?"},{"key":"p3_q5","text":"Do you think school rules are important?"},{"key":"p3_q6","text":"Are children unhappy with the school rules?"},{"key":"p3_q7","text":"What are the rules people should obey at work?"}]}}$json$::jsonb,now(),now())
